import {Renderer,pose,mul,transform,V,assetFetch} from './engine.js';
import {CATEGORIES,COLORS,DAY_NAMES,TASK_NAMES,makeBook,dayConfig,newProgress,complete,addProgress,canShelve,blocked,pathfind,transferBook} from './core.js';
const $=id=>document.getElementById(id),canvas=$('scene'),modal=$('modal'),SAVE='little-library-v1';
let renderer,assets,layout,state,keys=new Set(),paused=false,selected=null,clock=0,lastTime=0,saveTimer=0,toastTimer=0,nearby=null,modalNpc=null,targetPath=[],drag=null,trail=[],follow=false,cameraAngle=.68,zoom=26,cameraTarget=[0,.3,0],userStarted=false;
const dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function say(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=3.8}
function open(title,body,actions=[],type='작은 도서관'){keys.clear();targetPath=[];$('modal-title').textContent=title;$('modal-type').textContent=type;$('modal-body').innerHTML=body;$('modal-actions').replaceChildren();for(let a of actions){let b=document.createElement('button');b.textContent=a.label;if(a.primary)b.className='primary';b.disabled=!!a.disabled;b.onclick=a.run;$('modal-actions').append(b)}if(!modal.open)modal.showModal()}
function close(){modal.close();modalNpc=null;canvas.focus({preventScroll:true})}
function bookHtml(b){return `<div class="dialog-book"><strong>${escape(b.title)}</strong><br>${b.code} · ${CATEGORIES[b.category]}</div>`}
function newState(){return {version:1,day:1,score:0,player:{x:-3.4,z:7.2,angle:0,walk:0},cart:{x:4.9,z:6.3,angle:0,attached:false,books:[]},hands:[],machine:[],floor:[],npcs:[],progress:newProgress(),shelved:[],display:[],ticket:null,ended:false,elapsed:0}}
function populateDay(){let d=state.day;state.progress=newProgress();state.elapsed=0;state.ticket=null;state.hands=[];state.cart={x:4.9,z:6.3,angle:0,attached:false,books:[]};state.player={x:-3.4,z:7.2,angle:0,walk:0};targetPath=[];trail=[];state.shelved=[];state.display=[];
 let count=dayConfig(d).collected,locations=[{x:-2.5,z:2.2},{x:5.4,z:-3},{x:-6.9,z:-7.5}];state.floor=locations.slice(0,count).map((p,i)=>({...makeBook(`d${d}-floor${i}`,((d*2+i*3)%10)),...p}));
 state.cart.books=[makeBook(`d${d}-cart0`,(d+1)%10),makeBook(`d${d}-cart1`,(d+4)%10)];
 state.machine=Array.from({length:d+1},(_,i)=>makeBook(`d${d}-machine${i}`,(d+i+6)%10));
 let names=['하린','민준','지우','도윤','서연','유나','현우'];
 let defs=[['question','approach'],['question','desk'],['loan','desk'],['return','desk'],['issue','desk'],['roam','roam'],['roam','roam']];
 state.npcs=defs.map(([kind,mode],i)=>({id:`d${d}-npc${i}`,name:names[i],kind,mode,x:i===0?1.4:((i%3)-1)*3,z:i===0?4.0:9.7,angle:Math.PI,walk:0,status:'walking',category:(d*3+i*2)%10,book:makeBook(`d${d}-patron${i}`,(d*3+i*2)%10),path:[],wait:0,served:false,arrival:mode==='desk'?i*3.5:0,routeAt:0,roamIndex:i}));
 selected=state.cart.books[0]?.id||null;save();renderUI()
}
function safeLoad(){try{let s=JSON.parse(localStorage.getItem(SAVE));if(!s||s.version!==1||s.day<1||s.day>5||!s.player||!s.progress||!Array.isArray(s.npcs))return false;state=s;state.cart.attached=false;state.npcs.forEach(n=>{n.path=[];if(n.status==='talking')n.status=n.mode==='desk'?'waiting':'walking'});selected=state.hands[0]?.id||state.cart.books[0]?.id;return true}catch{return false}}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));$('save-status').textContent='진행 상황 자동 저장'}catch{$('save-status').textContent='저장 불가 · 브라우저 저장 공간 확인'}}
function carrying(){return [...state.hands,...(dist(state.player,state.cart)<2.4?state.cart.books:[])]}
function getSelected(){let list=carrying();return list.find(b=>b.id===selected)||list[0]}
function removeBook(id){for(let list of [state.hands,state.cart.books]){let i=list.findIndex(b=>b.id===id);if(i>=0)return list.splice(i,1)[0]}return null}
function actionDone(key,message){addProgress(state,key);save();renderUI();if(message)say(message)}
function renderUI(){let goal=dayConfig(state.day),p=state.progress;$('day-label').textContent=`DAY ${String(state.day).padStart(2,'0')} / 05`;$('day-title').textContent=DAY_NAMES[state.day-1];$('score').textContent=`${state.score}점`;
 let ratio=Object.keys(goal).reduce((s,k)=>s+Math.min(1,p[k]/goal[k]),0)/Object.keys(goal).length;$('progress').style.width=ratio*100+'%';$('tasks').innerHTML=Object.entries(goal).map(([k,v])=>`<div class="task ${p[k]>=v?'done':''}"><span class="task-icon">${p[k]>=v?'✓':'·'}</span><span>${TASK_NAMES[k]}</span><span class="task-count">${Math.min(v,p[k])} / ${v}</span></div>`).join('');
 let visible=state.npcs.filter(n=>n.status!=='gone'&&n.arrival<=state.elapsed);$('visitor-count').textContent=visible.length+'명';$('visitors').innerHTML=visible.map(n=>`<div class="visitor-row ${n.status==='waiting'||n.status==='asking'?'waiting':''}"><span class="visitor-dot"></span><span>${escape(n.name)} · ${n.kind==='roam'?'열람 중':n.status==='leaving'?'퇴실 중':n.kind==='question'?'문의':n.kind==='loan'?'대출':n.kind==='return'?'반납':'문제 접수'}</span><small>${n.status==='waiting'?'데스크 대기':n.status==='asking'?'사서를 찾는 중':''}</small></div>`).join('');
 $('finish-day').disabled=!complete(state)||state.ended;$('finish-day').textContent=state.ended?'5일 근무 완료':state.day===5?'5일간의 근무 마치기':'오늘의 업무 마치기';$('carry-info').textContent=`손에 ${state.hands.length} / 3권`;
 let list=carrying(),sel=getSelected();$('inventory').replaceChildren();for(let b of list){let el=document.createElement('button');el.className='book-slot'+(b.id===sel?.id?' selected':'');el.innerHTML=`<span class="book-spine" style="background:${COLORS[b.category]}">${b.code}</span><span class="book-title">${escape(b.title)}<small>${b.code} ${CATEGORIES[b.category]} · ${state.hands.includes(b)?'손':'카트'}</small></span>`;el.title='클릭하면 선택, I로 책 관리';el.onclick=()=>{selected=b.id;renderUI()};$('inventory').append(el)}for(let i=list.length;i<3;i++){let el=document.createElement('div');el.className='empty-slot';el.textContent='+';$('inventory').append(el)}
 $('cart-label').textContent=`북카트 · ${state.cart.attached?'연결됨':'분리됨'}`;$('cart-info').textContent=`${state.cart.books.length} / 12권 · ${state.cart.attached?'C로 놓기':'가까이에서 E로 연결'}`;
 $('day-tip').textContent=state.ticket?`접수된 문제: ${state.ticket.text} ${state.ticket.location==='computer'?'데스크 컴퓨터':'반납기'}에서 해결해 주세요.`:state.progress.shelved<goal.shelved?'책의 청구번호 앞 세 자리를 확인하세요. 000–900 서가와 맞아야 정리할 수 있어요.':'전시 공간에는 선택한 책을 올려둘 수 있어요. 남은 이용자 문의도 확인해 주세요.';
}
function nearest(){let p=state.player,candidates=[];const add=(type,obj,d,label)=>{if(d< (type==='shelf'?2.25:type==='desk'?2.55:1.9))candidates.push({type,obj,d,label})};
 for(let b of state.floor)add('book',b,dist(p,b),`책 줍기 · ${b.title}`);
 for(let n of state.npcs)if(['waiting','asking'].includes(n.status))add('npc',n,dist(p,n),`${n.name} · ${n.kind==='question'?'문의 듣기':n.kind==='loan'?'대출 처리':n.kind==='return'?'반납 처리':'문제 접수'}`);
 for(let s of layout.shelves){let d=Math.hypot(Math.max(Math.abs(p.x-s.x)-1.4,0),Math.max(Math.abs(p.z-s.z)-.5,0));add('shelf',s,d,`${s.code} ${CATEGORIES[s.category]} · 책 정리`)}
 add('cart',state.cart,dist(p,state.cart),'북카트 · '+(state.cart.attached?'놓기 / 책 관리':'연결 / 책 관리'));
 add('machine',layout.return,Math.hypot(Math.max(Math.abs(p.x-layout.return.x)-.9,0),Math.max(Math.abs(p.z-layout.return.z)-.75,0)),`반납기 · ${state.machine.length}권 수거`);
 add('desk',layout.desk,Math.hypot(Math.max(Math.abs(p.x-layout.desk.x)-2.2,0),Math.max(Math.abs(p.z-layout.desk.z)-.95,0)),'데스크 컴퓨터 · 도서 검색 / 업무');
 add('exhibition',layout.exhibition,Math.hypot(Math.max(Math.abs(p.x+8)-1.5,0),Math.max(Math.abs(p.z-3.3)-.65,0)),'전시 공간 · 책 배치');
 candidates.sort((a,b)=>a.d-b.d);return candidates[0]||null
}
function interact(){if(paused||state.ended||modal.open)return;if(!nearby){say('책, 서가, 이용자 또는 기기 가까이에서 E를 눌러 주세요.');return}let {type,obj}=nearby;
 if(type==='book'){let dest=state.cart.attached&&dist(state.cart,obj)<2.7&&state.cart.books.length<12?state.cart.books:state.hands;if(dest.length>=(dest===state.hands?3:12)){say('손이 가득 찼어요. 카트에 책을 담아 주세요.');return}state.floor=state.floor.filter(b=>b.id!==obj.id);dest.push(obj);selected=obj.id;actionDone('collected',`${obj.title}을 ${dest===state.hands?'손에 들었어요':'카트에 담았어요'}.`)}
 else if(type==='shelf'){let b=getSelected();if(!b){say('정리할 책이 없어요. 책을 줍거나 북카트를 가까이 가져오세요.');return}if(!canShelve(b,obj.category)){say(`${b.title}은 ${b.code} ${CATEGORIES[b.category]} 서가의 책이에요.`);return}removeBook(b.id);state.shelved.push({...b,x:obj.x,z:obj.z});actionDone('shelved',`${obj.code} 서가에 ${b.title}을 정리했어요.`)}
 else if(type==='cart')cartMenu();else if(type==='machine')machineMenu();else if(type==='desk')computerMenu();else if(type==='exhibition')exhibitionMenu();else if(type==='npc')talk(obj)
}
function toggleCart(){if(state.cart.attached){state.cart.attached=false;trail=[];say('북카트를 놓았어요. 책은 그대로 실려 있어요.')}else{if(dist(state.player,state.cart)>1.9){say('북카트 가까이에서 연결할 수 있어요.');return}state.cart.attached=true;trail=[{x:state.cart.x,z:state.cart.z},{x:state.player.x,z:state.player.z}];say('북카트를 연결했어요. 이동하면 책과 함께 따라옵니다.')}save();renderUI()}
function cartMenu(){open('북카트',`책 ${state.cart.books.length} / 12권이 담겨 있어요. 가까운 카트의 책은 서가 앞에서 바로 정리할 수 있어요.`,[{label:state.cart.attached?'카트 놓기':'카트 연결하기',primary:true,run:()=>{close();toggleCart()}},{label:'손에 든 책을 모두 카트에 담기',disabled:!state.hands.length||state.cart.books.length>=12,run:()=>{while(state.hands.length&&state.cart.books.length<12)transferBook(state.hands,state.cart.books,state.hands[0].id,12);save();renderUI();cartMenu()}},{label:'책 목록 관리',run:inventoryMenu},{label:'닫기',run:close}],'북카트')}
function inventoryMenu(){let list=carrying();open('책 목록',list.length?list.map(bookHtml).join(''):'가지고 있는 책이 없어요.',[...list.map(b=>({label:`${b.code} · ${b.title} ${state.hands.includes(b)?'→ 카트에 담기':'→ 손에 들기'}`,disabled:dist(state.player,state.cart)>2.4||(state.hands.includes(b)?state.cart.books.length>=12:state.hands.length>=3),run:()=>{if(state.hands.includes(b))transferBook(state.hands,state.cart.books,b.id,12);else transferBook(state.cart.books,state.hands,b.id,3);selected=b.id;save();renderUI();inventoryMenu()}})),{label:'닫기',run:close}],'책 관리')}
function machineMenu(){let jam=state.ticket?.location==='machine';open('무인 반납기',jam?'접수된 문제: 반납 슬롯에 종이가 끼었어요. 잠시 기기를 정지하고 종이를 제거해 주세요.':`반납된 책 ${state.machine.length}권을 수거할 수 있어요. 책 정리를 위해 북카트에 옮겨 주세요.`,[...(jam?[{label:'기기 정지 → 끼인 종이 제거 → 재시작',primary:true,run:()=>{state.ticket=null;close();actionDone('fixed','반납기가 정상 작동해요. 문제를 해결했어요.')}}]:[]),{label:state.cart.attached?'반납 도서 → 북카트에 수거':'반납 도서 → 손에 수거',disabled:!state.machine.length||!!jam,primary:!jam,run:()=>{let dest=state.cart.attached&&dist(state.player,state.cart)<2.4?state.cart.books:state.hands,cap=dest===state.hands?3:12;if(dest.length>=cap){say('책을 담을 공간이 부족해요. 먼저 서가에 정리해 주세요.');return}let count=0;while(state.machine.length&&dest.length<cap){dest.push(state.machine.shift());count++}selected=dest.at(-1)?.id;save();renderUI();close();say(`반납 도서 ${count}권을 수거했어요.`)}},{label:'닫기',run:close}],'반납 업무')}
function exhibitionMenu(){let b=getSelected();open('이달의 책 전시',`좋은 책을 골라 전시해 주세요.${b?bookHtml(b):'<p>책을 들고 오거나 북카트를 가까이 가져와 주세요.</p>'}`, [{label:'선택한 책 전시하기',disabled:!b||state.display.length>=4,primary:true,run:()=>{removeBook(b.id);state.display.push(b);close();actionDone('displayed',`${b.title}을 전시했어요.`)}},{label:'닫기',run:close}],'전시 공간')}
function computerMenu(){let queue=state.npcs.filter(n=>n.status==='waiting'&&n.mode==='desk');open('사서 데스크 컴퓨터',`<p>도서 검색 · 대출/반납 · 이용자 지원</p>${state.ticket?`<div class="modal-message">접수: ${escape(state.ticket.text)}</div>`:''}<p>데스크에서 기다리는 이용자 ${queue.length}명</p>`,[...queue.map(n=>({label:`${n.name} · ${n.kind==='loan'?'대출':n.kind==='return'?'반납':n.kind==='question'?'서가 문의':'문제 접수'} 처리`,primary:true,run:()=>talk(n)})),{label:'도서 검색 · 분류표 확인',run:()=>open('도서 검색',CATEGORIES.map((c,i)=>`<div class="catalog-row"><span>${String(i*100).padStart(3,'0')} · ${c}</span><span>${i<5?'뒤쪽':'앞쪽'} ${i%5+1}번째 서가</span></div>`).join(''),[{label:'컴퓨터로 돌아가기',run:computerMenu}],'청구번호 안내')},...(state.ticket?.location==='computer'?[{label:'프린터 연결 확인 → 대기열 초기화 → 시험 인쇄',primary:true,run:()=>{state.ticket=null;close();actionDone('fixed','안내 프린터를 복구했어요.')}}]:[]),{label:'닫기',run:close}],'사서 업무')}
function served(n,key,message){n.served=true;n.status='leaving';n.path=pathfind(n,{x:0,z:10},layout.colliders);close();actionDone(key,message)}
function talk(n){modalNpc=n.id;n.status=n.mode==='desk'?'waiting':'asking';
 if(n.kind==='question'){let c=n.category;let choices=[c,(c+3)%10,(c+7)%10].sort((a,b)=>a-b);open(`${n.name}의 문의`,`“${CATEGORIES[c]} 분야의 책을 찾고 있어요. 어느 서가로 가면 될까요?”<p>데스크 컴퓨터에서 분류표를 확인할 수도 있어요.</p>`,[...choices.map(cat=>({label:`${String(cat*100).padStart(3,'0')}번대 · ${CATEGORIES[cat]} 서가를 안내한다`,run:()=>{if(cat!==c){say('분야와 서가가 맞지 않아요. 분류표를 다시 확인해 주세요.');return}served(n,'questions',`${n.name}에게 알맞은 서가를 안내했어요.`)}})),{label:'잠시 기다려 주세요',run:close}],'이용자 문의')}
 else if(n.kind==='loan'){open(`${n.name}의 대출`,`“이 책을 빌리고 싶어요.”${bookHtml(n.book)}<p>회원증 확인 → 바코드 스캔 → 대출 등록 순서로 처리합니다.</p>`,[{label:'회원증 확인하고 책 대출 처리',primary:true,run:()=>served(n,'transactions',`${n.name}의 대출을 등록했어요. 반납 예정일을 안내했어요.`)},{label:'잠시 기다려 주세요',run:close}],'대출 업무')}
 else if(n.kind==='return'){open(`${n.name}의 반납`,`“다 읽은 책을 반납하러 왔어요.”${bookHtml(n.book)}<p>반납 처리한 책은 반납함으로 옮겨져요.</p>`,[{label:'바코드를 스캔하고 반납 처리',primary:true,run:()=>{state.machine.push(n.book);served(n,'transactions',`${n.name}의 반납을 처리했어요. 책은 반납함에 있어요.`)}},{label:'잠시 기다려 주세요',run:close}],'반납 업무')}
 else if(n.kind==='issue'){let loc=state.day%2===0?'machine':'computer';open(`${n.name}의 문제 접수`,loc==='machine'?'“반납기에 책을 넣으려는데 슬롯이 막힌 것 같아요.”':'“도서 검색 결과를 인쇄하려는데 안내 프린터가 작동하지 않아요.”',[{label:'문제를 접수하고 확인하겠다고 안내',primary:true,run:()=>{state.ticket={location:loc,text:loc==='machine'?'반납기 슬롯 막힘':'안내 프린터 연결 끊김'};n.served=true;n.status='leaving';n.path=pathfind(n,{x:0,z:10},layout.colliders);close();save();renderUI();say(`${loc==='machine'?'반납기':'데스크 컴퓨터'}에서 문제를 해결해 주세요.`)}},{label:'잠시 기다려 주세요',run:close}],'이용자 지원')}
}
function help(){open('작은 도서관에서 일하기','<div class="help-grid"><span>WASD / 방향키</span><span>사서 이동 · 화면의 위/아래/좌/우 방향</span><span>바닥 클릭</span><span>장애물을 피해 자동 이동</span><span>E</span><span>가까운 책·서가·이용자·기기 상호작용</span><span>C</span><span>북카트 연결 / 놓기</span><span>I</span><span>손과 북카트 사이 책 옮기기</span><span>Q / R</span><span>카메라 회전</span><span>마우스 휠</span><span>확대 / 축소</span><span>Esc / P</span><span>일시정지 또는 창 닫기</span></div><div class="modal-message">1. 반납기 옆 북카트에 가까이 가서 C로 연결하세요.<br>2. 바닥의 책을 줍고 반납함의 책을 수거하세요.<br>3. 책 청구번호에 맞는 000–900번대 서가 앞에서 E를 누르세요.<br>4. 이용자 문의, 데스크의 대출/반납, 접수된 문제를 처리하세요.<br>5. 전시 책까지 배치하면 하루를 마칠 수 있어요.</div>',[{label:userStarted?'근무로 돌아가기':'첫 근무 시작하기',primary:true,run:()=>{userStarted=true;close()}}],'조작 안내')}
function finishDay(){if(!complete(state)||state.ended)return;let final=state.day===5;open(final?'5일간의 근무를 마쳤어요':'오늘도 좋은 도서관이었어요',`<div class="summary-big">${state.score} <small>점</small></div><p>${state.day}일차 · ${DAY_NAMES[state.day-1]}</p><p>책 정리 ${state.progress.shelved}권 · 문의 ${state.progress.questions}건<br>대출·반납 ${state.progress.transactions}건 · 문제 해결 ${state.progress.fixed}건</p>${final?'<div class="modal-message">책들이 제자리를 찾고, 이용자들도 편안히 돌아갔어요. 작은 도서관의 든든한 사서가 되어 주셔서 고마워요.</div>':''}`,[{label:final?'완료하고 도서관 둘러보기':'다음 날 출근하기',primary:true,run:()=>{if(final){state.ended=true;save();renderUI();close()}else{state.day++;populateDay();close();say(`${state.day}일차 근무를 시작합니다.`)}}}],'근무 기록')}
function pause(){paused=!paused;$('pause-btn').textContent=paused?'근무 재개':'일시정지';keys.clear();if(paused)say('일시정지 중이에요. 근무 재개 버튼이나 P를 눌러 주세요.')}
function moveEntity(n,dx,dz,r=.28){let moved=false;if(!blocked(n.x+dx,n.z,layout.colliders,r)){n.x+=dx;moved|=Math.abs(dx)>.0001}if(!blocked(n.x,n.z+dz,layout.colliders,r)){n.z+=dz;moved|=Math.abs(dz)>.0001}if(moved){n.angle=Math.atan2(dx,dz);n.walk+=Math.hypot(dx,dz)*5}return moved}
function followPath(n,dt,speed=1.3){if(!n.path.length)return false;let p=n.path[0],d=dist(n,p);if(d<.13){n.path.shift();return true}let step=Math.min(d,speed*dt);return moveEntity(n,(p.x-n.x)/d*step,(p.z-n.z)/d*step)}
function updateNpcs(dt){let queue=state.npcs.filter(n=>n.mode==='desk'&&!n.served&&n.arrival<=state.elapsed);queue.sort((a,b)=>a.arrival-b.arrival);
 for(let n of state.npcs){if(n.arrival>state.elapsed||n.status==='gone')continue;n.routeAt-=dt;n.wait+=dt;
 if(n.status==='leaving'){if(!n.path.length)n.path=pathfind(n,{x:0,z:10.1},layout.colliders);followPath(n,dt,1.6);if(dist(n,{x:0,z:10.1})<.7)n.status='gone';continue}
 if(n.mode==='roam'){if(!n.path.length&&n.routeAt<=0){let spots=[{x:-2.3,z:-7.9},{x:6.7,z:3.8},{x:2.2,z:-3.1},{x:-10.8,z:1.5},{x:0,z:6.5}];let goal=spots[n.roamIndex++%spots.length];n.path=pathfind(n,goal,layout.colliders);n.routeAt=3}followPath(n,dt,.95);continue}
 if(n.mode==='approach'){if(dist(n,state.player)<1.45){n.status='asking';n.angle=Math.atan2(state.player.x-n.x,state.player.z-n.z);n.path=[]}else{n.status='walking';if(n.routeAt<=0){n.path=pathfind(n,state.player,layout.colliders);n.routeAt=1.1}followPath(n,dt,1.3)}continue}
 let index=queue.indexOf(n),goal={x:-6.0+Math.min(index,3)*1.10,z:9.1};if(dist(n,goal)<.24){n.status='waiting';n.angle=Math.PI;n.path=[]}else{n.status='walking';if(n.routeAt<=0){n.path=pathfind(n,goal,layout.colliders);n.routeAt=2}followPath(n,dt,1.1)}
 }
}
function updatePlayer(dt){let p=state.player,dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dz=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0),moving=dx||dz;
 if(moving){targetPath=[];let length=Math.hypot(dx,dz),c=Math.cos(cameraAngle),s=Math.sin(cameraAngle),wx=(dx*c+dz*s)/length,wz=(-dx*s+dz*c)/length;dx=wx;dz=wz}
 else if(targetPath.length){let goal=targetPath[0],d=dist(p,goal);if(d<.14){targetPath.shift();return}dx=(goal.x-p.x)/d;dz=(goal.z-p.z)/d;moving=true}
 if(moving){let old={x:p.x,z:p.z},speed=state.cart.attached?2.55:3.5;moveEntity(p,dx*speed*dt,dz*speed*dt);
 if(state.cart.attached){trail.push({x:p.x,z:p.z});let distance=0,target=trail[0];for(let i=trail.length-1;i>0;i--){distance+=dist(trail[i],trail[i-1]);if(distance>=1.35){target=trail[i-1];if(i>1)trail.splice(0,i-1);break}}let d=dist(state.cart,target);if(d>.03){let step=Math.min(d,dt*speed*1.8),cx=(target.x-state.cart.x)/d*step,cz=(target.z-state.cart.z)/d*step;moveEntity(state.cart,cx,cz,.40)}if(dist(p,state.cart)>2.1){p.x=old.x;p.z=old.z;targetPath=[];if(clock-saveTimer>1)say('카트가 걸렸어요. 뒤로 조금 움직이거나 C로 놓고 방향을 바꿔 주세요.');saveTimer=clock}}
 }
 if(keys.has('q'))cameraAngle-=dt*.7;if(keys.has('r'))cameraAngle+=dt*.7
}
let labelEls=new Map();function label(id,text,x,y,z,cls=''){let el=labelEls.get(id);if(!el){el=document.createElement('div');el.className='world-label '+cls;$('labels').append(el);labelEls.set(id,el)}el.textContent=text;let p=renderer.project(x,y,z);el.style.left=p.x+'px';el.style.top=p.y+'px';el.hidden=p.x<0||p.y<0||p.x>canvas.clientWidth||p.y>canvas.clientHeight;return el}
function updateLabels(){let ids=new Set();for(let s of layout.shelves){let id='s-'+s.code;ids.add(id);label(id,`${s.code} ${CATEGORIES[s.category]}`,s.x,2.96,s.z)}for(let n of state.npcs){if(n.arrival>state.elapsed||n.status==='gone')continue;let id=n.id;ids.add(id);let t=n.status==='asking'?'? '+n.name+' · 문의':n.status==='waiting'?n.name+' · 대기':n.name;label(id,t,n.x,2.0,n.z,'npc-label')}label('player','사서 · 나',state.player.x,2,state.player.z);ids.add('player');for(let b of state.floor){ids.add(b.id);label(b.id,`▱ ${b.code}`,b.x,.22,b.z,'book-label')}for(let[id,el]of labelEls)if(!ids.has(id)){el.remove();labelEls.delete(id)}}
function character(n,tint=[1,1,1]){let active=n===state.player?(keys.size>0||targetPath.length>0):n.path?.length>0;return {asset:assets.librarian,matrix:pose(n.x,0,n.z,n.angle),tint,animate:(node,local)=>{if(!active)return local;let name=node.name,sign=name.endsWith('L')?1:-1;if(name.startsWith('leg.')||name.startsWith('arm.')){let a=Math.sin(n.walk)*.32*sign*(name.startsWith('arm')?-1:1);return mul(local,transform([0,0,0],[Math.sin(a/2),0,0,Math.cos(a/2)]))}return local}}}
function instances(){let result=[{asset:assets.library,matrix:pose(0,0,0)},character(state.player),{asset:assets.cart,matrix:pose(state.cart.x,0,state.cart.z,state.cart.angle)}];let addBook=(b,x,y,z,a=0)=>{let hex=COLORS[b.category];let color=[1,3,5].map(i=>Math.pow(parseInt(hex.slice(i,i+2),16)/255,2.2));result.push({asset:assets.book,matrix:pose(x,y,z,a),bookColor:[...color,1]})};
 for(let b of state.floor)addBook(b,b.x,.01,b.z,parseInt(b.id.replace(/\D/g,''))*1.3);
 state.cart.books.forEach((b,i)=>{let ox=(i%3-1)*.33,oy=i<6?1.10:.42,oz=(Math.floor(i/3)%2-.5)*.33,c=Math.cos(state.cart.angle),s=Math.sin(state.cart.angle);addBook(b,state.cart.x+ox*c+oz*s,oy,state.cart.z-ox*s+oz*c,state.cart.angle)});
 state.hands.forEach((b,i)=>addBook(b,state.player.x+Math.sin(state.player.angle)*.43,.71+i*.075,state.player.z+Math.cos(state.player.angle)*.43,state.player.angle));
 state.display.forEach((b,i)=>addBook(b,-9.05+i*.6,1.20,3.45,0));
 for(let n of state.npcs)if(n.status!=='gone'&&n.arrival<=state.elapsed)result.push(character(n,[[1.55,.95,.9],[.9,1.15,1.7],[1.6,1.3,.7],[1.15,.9,1.4]][n.roamIndex%4]));return result
}
function tick(now){let dt=Math.min((now-lastTime)/1000||0,.04);lastTime=now;clock+=dt;if(state&&!paused&&!modal.open){if(!state.ended)state.elapsed+=dt;updatePlayer(dt);updateNpcs(dt);if(clock-saveTimer>4){saveTimer=clock;save();renderUI()}}if(state){let target=follow?[state.player.x,.3,state.player.z]:[0,.3,0];cameraTarget=cameraTarget.map((v,i)=>v+(target[i]-v)*Math.min(dt*4,1));let eye=[cameraTarget[0]+Math.sin(cameraAngle)*28,cameraTarget[1]+25,cameraTarget[2]+Math.cos(cameraAngle)*28],aspect=canvas.clientWidth/canvas.clientHeight,effectiveZoom=follow?zoom:Math.max(zoom,32/aspect);renderer.render(instances(),eye,cameraTarget,effectiveZoom);updateLabels();nearby=nearest();$('prompt').hidden=!nearby||paused||modal.open;if(nearby)$('prompt').innerHTML=`<kbd>E</kbd> ${escape(nearby.label)}`;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}}requestAnimationFrame(tick)}
window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();if(modal.open){if(k==='Escape')close();return}if(['w','a','s','d','q','r','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k))keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k==='c'&&!paused)toggleCart();if(k==='i')inventoryMenu();if(k==='h')help();if(k==='p'||k==='Escape')pause()});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(state)save()}});window.addEventListener('beforeunload',()=>{if(state)save()});
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.focus();drag={button:e.button,x:e.clientX,y:e.clientY,ox:e.clientX,oy:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag&&drag.button===2){cameraAngle+=(e.clientX-drag.x)*.008;drag.x=e.clientX;drag.y=e.clientY}});canvas.addEventListener('pointerup',e=>{if(drag&&drag.button===0&&Math.hypot(e.clientX-drag.ox,e.clientY-drag.oy)<6&&!modal.open&&!paused&&state){let dest=renderer.ground(e.clientX,e.clientY);targetPath=pathfind(state.player,dest,layout.colliders);if(!targetPath.length)say('그 위치로 이동할 수 없어요. 가까운 통로를 클릭해 주세요.')}drag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(9,Math.min(34,zoom+e.deltaY*.012))},{passive:false});
$('close-modal').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close()});$('help-btn').onclick=help;$('pause-btn').onclick=pause;$('finish-day').onclick=finishDay;$('overview-btn').onclick=()=>{follow=false;zoom=26;cameraAngle=.68};$('follow-btn').onclick=()=>{follow=true;zoom=13};$('reset-btn').onclick=()=>open('근무 기록을 초기화할까요?','저장된 진행 상황을 지우고 1일차부터 다시 시작합니다.',[{label:'1일차부터 다시 시작',run:()=>{state=newState();populateDay();close();paused=false;state.ended=false;say('새로운 5일 근무를 시작해요.')}},{label:'계속 근무하기',primary:true,run:close}]);$('mobile-e').onclick=interact;for(let b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(b.dataset.move);b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>keys.delete(b.dataset.move));b.addEventListener('pointercancel',()=>keys.delete(b.dataset.move))}
async function init(){try{renderer=new Renderer(canvas);let loaded=await Promise.all(['library','librarian','cart','book'].map(n=>renderer.load(`assets/${n}.glb`)));assets=Object.fromEntries(['library','librarian','cart','book'].map((n,i)=>[n,loaded[i]]));let response=await assetFetch('assets/layout.json');if(!response.ok)throw Error('도서관 배치 로드 실패');layout=await response.json();let restored=safeLoad();if(!restored){state=newState();populateDay()}renderUI();$('loading').remove();requestAnimationFrame(tick);if(!restored)help();else{userStarted=true;say('저장된 근무를 이어갑니다.')}window.libraryGame={get state(){return state},get layout(){return layout},get renderer(){return renderer},get nearby(){return nearby},get assets(){return assets},interact,computerMenu,machineMenu,talk,finishDay,inventoryMenu,close,renderUI,save,populateDay,toggleCart,getSelected,get path(){return targetPath},goTo:(x,z)=>targetPath=pathfind(state.player,{x,z},layout.colliders)};
}catch(e){console.error(e);$('loading-text').textContent=e.message;$('loading').insertAdjacentHTML('beforeend','<p>README의 실행 방법을 확인해 주세요. HTML 파일을 직접 열면 모델을 불러올 수 없습니다.</p>')}}
